        svg: '<svg viewBox="0 0 300 292" xmlns="http://www.w3.org/2000/svg"><g font-family="Georgia,serif" text-anchor="middle"><circle cx="150" cy="26" r="9" fill="none" stroke="var(--panel-line-bright)" stroke-width="1" stroke-dasharray="2 3"/><text x="168" y="29" fill="var(--faint)" font-size="5.8" text-anchor="start">KETHER — NOT EMBRACED</text><path d="M 92 62 A 60 60 0 0 0 208 62" fill="none" stroke="var(--amber)" stroke-width="2.4" stroke-linecap="round"/><circle cx="92" cy="62" r="3" fill="var(--gold)"/><circle cx="208" cy="62" r="3" fill="var(--gold)"/><text x="86" y="56" fill="var(--gold)" font-size="6.2" text-anchor="end">BINAH</text><text x="214" y="56" fill="var(--gold)" font-size="6.2" text-anchor="start">CHOKMAH</text><text x="150" y="44" fill="var(--m3)" font-size="6.2" letter-spacing="0.8">WATERS ABOVE THE FIRMAMENT</text><circle cx="150" cy="150" r="44" fill="#d0ad6d0d" stroke="var(--amber)" stroke-width="1.8"/><text x="150" y="145" fill="var(--gold)" font-size="8.4" letter-spacing="0.6">THE FIRMAMENT</text><text x="150" y="157" fill="var(--muted)" font-size="5.4">CHESED · GEBURAH · TIPHARETH</text><text x="150" y="166" fill="var(--muted)" font-size="5.4">NETZACH · HOD</text><polygon points="150,194 100,250 200,250" fill="#d97b7b12" stroke="var(--amber)" stroke-width="1.8"/><circle cx="150" cy="194" r="2.6" fill="var(--gold)"/><text x="163" y="200" fill="var(--gold)" font-size="6.2" text-anchor="start">YESOD — APEX</text><text x="150" y="238" fill="#d97b7b" font-size="6.6" letter-spacing="0.8">CONSUMING FIRE</text><text x="150" y="262" fill="var(--gold)" font-size="6.2">MALKUTH — BASE</text><text x="150" y="282" fill="var(--muted)" font-size="7.6" letter-spacing="2">NINE SEPHIROTH · ALL BUT KETHER</text></g></svg>',
