        svg: '<svg viewBox="0 0 300 260" xmlns="http://www.w3.org/2000/svg"><g fill="none" stroke="var(--amber)" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><path d="M124 74q0-46 26-46t26 46"/><path d="M138 40q12-8 24 0v46q0 14-12 14t-12-14Z"/><path d="M150 44v42"/><path d="M120 96q30-12 60 0v148h-60Z"/><path d="M120 100 60 108q-12 2-10 14t14 10l60-10"/><path d="M180 100 240 108q12 2 10 14t-14 10l-60-10"/><path d="M64 122l52 22M236 122l-52 22"/></g><g><polygon points="128,126 172,126 150,160" fill="#63dfca1f" stroke="var(--m3)" stroke-width="1.8"/></g><g font-family="Georgia,serif" text-anchor="middle"><text x="150" y="180" fill="var(--m3)" font-size="7" letter-spacing="1.2">THE TRIANGLE OF WATER</text><text x="46" y="72" fill="var(--faint)" font-size="5.6">ELBOWS LEVEL</text><text x="46" y="80" fill="var(--faint)" font-size="5.6">WITH THE SHOULDERS</text><text x="254" y="72" fill="var(--faint)" font-size="5.6">HANDS TOGETHER,</text><text x="254" y="80" fill="var(--faint)" font-size="5.6">THUMBS AND FOREFINGERS</text><text x="150" y="234" fill="var(--gold)" font-size="9" letter-spacing="2.4">THE SIGN OF PRACTICUS</text><text x="150" y="248" fill="var(--muted)" font-size="6">APEX DOWNWARDS — THE ELEMENT OF THE GRADE</text></g></svg>',
